import math

def calculate_stock_volatility(prices):
    """
    Calculates the volatility (standard deviation) of daily returns over the most recent 31 prices.
    Returns a float volatility or None if input is invalid or insufficient data.
    """
    if not prices or len(prices) < 31:
        return None

    window = prices[-31:]
    for p in window:
        if not isinstance(p, (int, float)) or p <= 0:
            return None

    returns = [(window[i] / window[i - 1] - 1) for i in range(1, len(window))]
    mean_return = sum(returns) / len(returns)
    variance = sum((r - mean_return) ** 2 for r in returns) / len(returns)
    return math.sqrt(variance)

